package cli

import (
	"context"
	"fmt"

	"github.com/spf13/cobra"
)

type inputFilesContextKey struct{}

// AttachPromptInputFiles lets `captain prompt run|render <prompt> [files...]`
// take input files after the prompt. The commands are generated by
// clicky.GenerateCLI, whose actions take at most one positional id, so this
// wraps them after generation: the files ride the command context to the
// action, which binds them as Options.InputFiles.
func AttachPromptInputFiles(root *cobra.Command) error {
	for _, verb := range []string{"run", "render"} {
		cmd, _, err := root.Find([]string{"prompt", verb})
		if err != nil || cmd == nil || cmd.Name() != verb || cmd.RunE == nil {
			return fmt.Errorf("prompt input files require a generated prompt %s command", verb)
		}
		run := cmd.RunE
		cmd.Use = verb + " [prompt] [files...] [flags]"
		cmd.Args = cobra.ArbitraryArgs
		cmd.RunE = func(cmd *cobra.Command, args []string) error {
			if len(args) > 1 {
				cmd.SetContext(context.WithValue(cmd.Context(), inputFilesContextKey{}, args[1:]))
				args = args[:1]
			}
			return run(cmd, args)
		}
	}
	return nil
}

func inputFilesFromContext(ctx context.Context) []string {
	files, _ := ctx.Value(inputFilesContextKey{}).([]string)
	return files
}
